import type { GameRuntime } from '../types/game/index.ts';

/** Invoke a zero-arg method extracted from `game` (ESLint-safe); preserves `this`. */
export function callGameVoid(game: GameRuntime, method: unknown): void {
    if (typeof method === 'function') {
        (method as (this: GameRuntime) => void).call(game);
    }
}

/** Invoke a method on `game` with args; returns `undefined` if not a function. */
export function callGame<T>(game: GameRuntime, method: unknown, ...args: unknown[]): T | undefined {
    if (typeof method !== 'function') return undefined;
    return (method as (this: GameRuntime, ...a: unknown[]) => T).call(game, ...args);
}

/** Mastery scaler on `game` (returns finite number or fallback). */
export function callGameNumber(game: GameRuntime, method: unknown, amount: number, fallback = amount): number {
    const out = callGame<number>(game, method, amount);
    return typeof out === 'number' && Number.isFinite(out) ? out : fallback;
}
